export interface ChatModelChoice {
  provider: string;
  model: string;
  effort: string;
}

export interface ModelOptionInfo {
  id: string;
  label: string;
  // Levels the model accepts, lowest first; empty when it has none.
  efforts: string[];
  defaultEffort?: string;
  // An account's models only: its tier ('basic' reads "Standard"), what a
  // message costs, and false where it cannot see pictures.
  tier?: string;
  credits?: number;
  images?: boolean;
}

// One lot of credits in GET /account, with what is left and what it started as.
export interface CreditLot {
  kind: string;
  credits: number;
  granted: number;
  expires_at: string | null;
}

// One row of the account's usage table: a chat's messages on one day, or a
// print report and what it earned. The gateway never sees a chat's title, so
// a chat's row names it by its id; the app keeps the titles.
export type CreditActivity =
  | { date: string; chat_id: string | null; tier: 'basic' | 'expert'; messages: number; credits: number }
  | { date: string; kind: 'report'; title: string; credits: number };

// The part of the account's answer the message box and Account read. Dates
// are the gateway's days, YYYY-MM-DD.
export interface CreditAccount {
  credits: { total: number; lots: CreditLot[] };
  plan: {
    id: string;
    name: string;
    renews_at: string | null;
    unlimited_basic: boolean;
  } | null;
  v1_subscription: { plan_id: string; cents: number; period: 'month' | 'year' } | null;
  usage_30d: {
    credits: number;
    // Only days with a charge.
    days: { date: string; credits: number }[];
    // Newest first.
    activity: CreditActivity[];
  };
}

export interface ProviderModelsInfo {
  id: string;
  label: string;
  defaultModel: string;
  state: 'loading' | 'ready' | 'failed';
  models: ModelOptionInfo[];
}

export interface ModelCatalogPayload {
  defaultProvider: string;
  providers: ProviderModelsInfo[];
}

// The host's classification of an attachment. Model/project files go through
export type SetupPhase = 'idle' | 'checking' | 'verified' | 'error';

export interface SetupStatusPayload {
  phase: SetupPhase;
  provider?: string;
  elapsedMs?: number;
  error?: AgentErrorInfo;
  warning?: string;
}

// A provider with a stored key, as the host describes it: never the key, only
// its hint ("sk-ant-…a3F9", its known start and last 4 characters), and
// whether the provider refused that key in this session.
export interface SavedKeyInfo {
  provider: string;
  hint: string;
  rejected: boolean;
  // The signed-in email, for the JusPrin account ('jusprin'), whose
  // credential is a sign-in rather than a key.
  account?: string;
}

// Where a JusPrin sign-in has got to (cloud_account capability). 'browser'
// waits for the person in the browser tab at `url`; 'checking' asks the
// server about the account. `expired` says the stored sign-in has ended.
export interface AccountStatusPayload {
  phase: 'idle' | 'browser' | 'checking';
  url?: string;
  expired?: boolean;
  error?: AgentErrorInfo;
  warning?: string;
}

export interface SetupKeysPayload {
  keys: SavedKeyInfo[];
}

  copyName?: string; // the copy a change to a stock filament is saved as
}

// What JusPrin copied from JusPrin v1 on this computer at its first start,
// as the welcome-back window lists it (canvas boards V1-01 to V1-03).
export interface WelcomeBackPayload {
  kind: 'welcome_back';
  printers: string[];
  presets: string[]; // filament and process presets
  connections: string[]; // printers with a network connection
  preferences: boolean;
  failed: string[]; // files that could not be copied
  unusable: string[]; // imported presets OrcaSlicer could not load
}

// File › Import › Import from OrcaSlicer…'s window (canvas boards
